/* Minimal, reusable button */
.btn {
  display: inline-block;
  background: var(--button-bg);
  color: var(--button-text);
  border: none;
  border-radius: 6px;
  padding: 8px 19px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(185, 45, 90, 0.06);
  transition: background 0.18s, color 0.18s, opacity 0.17s, box-shadow 0.13s;
  outline: none;
}
.btn:hover, .btn:focus-visible {
  background: var(--button-bg-hover);
  color: #fff;
  opacity: 1;
}
.btn:disabled, .btn[disabled] {
  background: var(--button-disabled);
  color: #fff;
  opacity: 0.7;
  cursor: not-allowed;
  box-shadow: none;
}

/* Button for neutral/secondary actions */
.btn-neutral {
  background: var(--button-neutral);
  color: var(--text-primary);
  font-weight: 600;
  border: 1px solid var(--border-color);
}
.btn-neutral:hover, .btn-neutral:focus-visible {
  background: var(--button-neutral-hover);
  color: var(--text-primary);
